$loan=$inventoryLoanActionState['loan']??$inventory->loan($loanId);$loanActionText=static fn(string$s,array$v=[]):string=>\Kulturhus\Native\Language\InventoryLoanActionMessages::text($s,$managerLanguageMessages??[],$v);$loanActionRoute=$inventoryLoanActionState['route']??['view'=>'inventory','tab'=>'loans','loan'=>$loanId];$loanPostedAction=input($_POST,'target')===$loanId?input($_POST,'action'):'';$loanPostedData=is_array($_POST['data']??null)?$_POST['data']:[];$loanFormData=static fn(string$op):array=>$loanPostedAction==='inventory-'.$op?$loanPostedData:[];
